INSERT INTO public.telescope_entries VALUES (19576, 'a23c7ef6-2e26-403b-9676-b5d919e177d6', 'a23c7ef7-2bc5-4ff9-b796-d44fbc067f99', NULL, true, 'query', '{"connection":"pgsql","driver":"pgsql","bindings":[],"sql":"select a.attname as name, t.typname as type_name, format_type(a.atttypid, a.atttypmod) as type, (select tc.collcollate from pg_catalog.pg_collation tc where tc.oid = a.attcollation) as collation, not a.attnotnull as nullable, (select pg_get_expr(adbin, adrelid) from pg_attrdef where c.oid = pg_attrdef.adrelid and pg_attrdef.adnum = a.attnum) as default, a.attgenerated as generated, col_description(c.oid, a.attnum) as comment from pg_attribute a, pg_class c, pg_type t, pg_namespace n where c.relname = ''lapses'' and n.nspname = current_schema() and a.attnum > 0 and a.attrelid = c.oid and a.atttypid = t.oid and n.oid = c.relnamespace order by a.attnum","time":"1.73","slow":false,"file":"\/var\/www\/html\/artisan","line":16,"hash":"25b2aab4b440892659e027fd1409375b","hostname":"4046774c8e01"}', '2026-07-11 21:58:38');
