INSERT INTO public.telescope_entries VALUES (23865, 'a23c90c3-2847-402c-970b-56f2f009e062', 'a23c90c4-8f0a-428f-b66a-ef3be39b6501', NULL, true, 'query', '{"connection":"pgsql","driver":"pgsql","bindings":[],"sql":"select a.attname as name, t.typname as type_name, format_type(a.atttypid, a.atttypmod) as type, (select tc.collcollate from pg_catalog.pg_collation tc where tc.oid = a.attcollation) as collation, not a.attnotnull as nullable, (select pg_get_expr(adbin, adrelid) from pg_attrdef where c.oid = pg_attrdef.adrelid and pg_attrdef.adnum = a.attnum) as default, a.attgenerated as generated, col_description(c.oid, a.attnum) as comment from pg_attribute a, pg_class c, pg_type t, pg_namespace n where c.relname = ''schedules'' and n.nspname = current_schema() and a.attnum > 0 and a.attrelid = c.oid and a.atttypid = t.oid and n.oid = c.relnamespace order by a.attnum","time":"1.85","slow":false,"file":"\/var\/www\/html\/artisan","line":16,"hash":"4801885da44359614f9b0ccb0008a1ce","hostname":"4046774c8e01"}', '2026-07-11 22:48:24');
